@@ -0,0 +1,15 @@
+import { createEventCard } from './event-card.js';
+import { sortBy } from '../lib/collections.js';
+
+export function orderEvents(events) {
+  const entries = events.map((event) => ({
+    event,
+    card: createEventCard(event),
+    time: new Date(event.startsAt).getTime(),
+  }));
+  return sortBy(entries, (entry) => entry.time).map(({ event, card }) => ({ event, card }));
+}
+
+export function buildAgenda(events) {
+  return orderEvents(events).map(({ card }) => card);
+}
