+import { orderEvents } from './agenda.js';
+import { summarizeAttendance } from './attendance.js';
+
+function signupsFor(signupsByEvent, id) {
+  if (signupsByEvent instanceof Map) return signupsByEvent.get(id) ?? [];
+  if (signupsByEvent && Object.hasOwn(signupsByEvent, id)) return signupsByEvent[id] ?? [];
+  return [];
+}
+
+export function buildOrganizerDigest(events, signupsByEvent = {}) {
+  return orderEvents(events).map(({ event, card }) => ({
+    ...card,
+    ...summarizeAttendance(event, signupsFor(signupsByEvent, card.id)),
+  }));
+}

